/**
 * Осенняя листва — фоновый слой строки школы в сайдбаре (сентябрь).
 *
 * Живёт отдельным файлом не ради переиспользования, а ради веса: обвод листа —
 * 7.5 КБ данных, и в компоненте навигации они забивали всё остальное. Пропсов
 * нет намеренно: потребитель один, а плотность и палитра здесь не «настройка»,
 * а часть рисунка — понадобится второй вариант, тогда и появится параметр.
 *
 * Слой рассчитан на родителя с `relative isolate overflow-hidden`: `-z-10`
 * кладёт листья поверх фона кнопки, но под её текст, а обрезает их скругление
 * самой кнопки.
 */
export function AutumnLeaves() {
  return (
    <span
      aria-hidden
      className="pointer-events-none absolute inset-0 -z-10 text-orange-500 group-data-[collapsible=icon]:hidden"
    >
      {LEAVES.map((leaf, i) => (
        <MapleLeaf key={i} className="animate-leaf-fall absolute top-0" style={leaf} />
      ))}
    </span>
  )
}

